16	namespace KvSort {
17	using namespace AscendC;
18	
19	constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
20	constexpr int64_t BLOCK_BYTES = 32;
21	constexpr int64_t INT32_ONE_BLOCK_NUM = 8;
22	constexpr float MIN_FP32 = -3.4e38f;
23	constexpr int64_t DST_BLK_STRIDE = 1;
24	constexpr int64_t DST_REP_STRIDE = 8;
25	constexpr int64_t MERGE_LIST_TWO = 2;
26	constexpr int64_t MERGE_LIST_THREE = 3;
27	constexpr int64_t MERGE_LIST_FOUR = 4;
28	constexpr int64_t MERGE_LIST_IDX_TWO = 2;
29	constexpr int64_t MERGE_LIST_IDX_THREE = 3;
30	constexpr int64_t MAX_MRGSORT_LIST = 4;
31	constexpr int64_t WORK_GM_NUM = 2;
32	
33	__aicore__ inline int64_t CeilDiv(int64_t a, int64_t b)
34	{
35	    if (b == 0) return 0;
36	    return (a + b - 1) / b;
