// Wait functions for pipeline synchronization
__aicore__ inline void WaitMte2Done() {
    event_t evt = static_cast<event_t>(GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE2_S));
    AscendC::SetFlag<AscendC::HardEvent::MTE2_S>(evt);
    AscendC::WaitFlag<AscendC::HardEvent::MTE2_S>(evt);
}

__aicore__ inline void WaitMte3Done() {
    event_t evt = static_cast<event_t>(GetTPipePtr()->FetchEventID(AscendC::HardEvent::MTE3_S));
    AscendC::SetFlag<AscendC::HardEvent::MTE3_S>(evt);
    AscendC::WaitFlag<AscendC::HardEvent::MTE3_S>(evt);
}

__aicore__ inline void WaitVDone() {
    event_t evt = static_cast<event_t>(GetTPipePtr()->FetchEventID(AscendC::HardEvent::V_S));
    AscendC::SetFlag<AscendC::HardEvent::V_S>(evt);
    AscendC::WaitFlag<AscendC::HardEvent::V_S>(evt);
}

template <typename T>
class SortKernel {
public:
    __aicore__ inline SortKernel() {}

    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR output,
        int64_t totalRows, int64_t sortDimLength, int64_t descending,
        AscendC::TPipe *pipe) {
        this->pipe = pipe;
        this->totalRows = totalRows;
        this->sortDimLength = sortDimLength;
        this->descending = descending;
        this->sortNum = AlignUp(sortDimLength, sizeof(float));
        this->repeatTimes = sortNum / ONE_REPEAT_SORT_NUM;

        inputGm.SetGlobalBuffer((__gm__ T *)input, totalRows * sortDimLength);
        outputGm.SetGlobalBuffer((__gm__ T *)output, totalRows * sortDimLength);

        // Buffer sizes:
        // - float32 row buffer: sortNum * sizeof(float) for input
        // - float32 sort output: sortNum * sizeof(float) * 2 (key-index pairs)
        // - float32 temp buffer: sortNum * sizeof(float) * 2
        // - int32 index buffer: sortNum * sizeof(int32_t)
        int64_t rowFloatBytes = this->sortNum * sizeof(float);
        int64_t sortPairBytes = this->sortNum * sizeof(float) * 2;
        int64_t totalBuf = rowFloatBytes * 2 + sortPairBytes * 2;

        pipe->InitBuffer(inQueue, 1, totalBuf);
        pipe->InitBuffer(outQueue, 1, rowFloatBytes);
    }

    __aicore__ inline void Process() {
        int64_t blockIdx = GetBlockIdx();
        int64_t coreNum = GetBlockNum();
        int64_t rowsPerCore = (totalRows + coreNum - 1) / coreNum;
        int64_t coreStart = blockIdx * rowsPerCore;
        int64_t coreEnd = coreStart + rowsPerCore;
        if (coreEnd > totalRows) coreEnd = totalRows;

        for (int64_t row = coreStart; row < coreEnd; ++row) {
            CopyIn(row);
            Compute(row);
            CopyOut(row);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t row) {
        LocalTensor<uint8_t> inBuf = inQueue.AllocTensor<uint8_t>();

        // For fp16/bf16: need to cast to fp32 first
        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: copy directly to float buffer
            LocalTensor<float> rowBuf = inBuf.ReinterpretCast<float>();
            uint64_t copyNums = sortDimLength;
            uint64_t copyNumsAligned = sortNum;

            // Fill with -inf for padding
            AscendC::Duplicate(rowBuf, static_cast<float>(-__builtin_inff()), copyNumsAligned);
            WaitVDone();

            // Copy actual data from GM
            bool needPad = (copyNums % 8 != 0);
            uint8_t rightPad = needPad ? static_cast<uint8_t>(8 - (copyNums % 8)) : 0;
            AscendC::DataCopyExtParams intriParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(copyNums * sizeof(float)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0));
            AscendC::DataCopyPadExtParams<float> padParams(
                needPad, 0, rightPad, static_cast<float>(-__builtin_inff()));
            AscendC::DataCopyPad(rowBuf, inputGm[row * sortDimLength], intriParams, padParams);
            WaitMte2Done();

            // Negate for ascending sort
            if (!descending) {
                AscendC::Muls(rowBuf, rowBuf, (float)(-1), copyNums);
                WaitVDone();
            }
        } else {
            // FP16/BF16: cast to fp32
            LocalTensor<float> rowBuf = inBuf.ReinterpretCast<float>();
            uint64_t copyNums = sortDimLength;
            uint64_t copyNumsAligned = sortNum;

            // Fill with -inf
            AscendC::Duplicate(rowBuf, static_cast<float>(-__builtin_inff()), copyNumsAligned);
            WaitVDone();

            // Copy from GM to cast buffer (second half of inBuf)
            int64_t castOffsetBytes = sortNum * sizeof(float);
            LocalTensor<T> castBuf = inBuf[castOffsetBytes].ReinterpretCast<T>();
            AscendC::DataCopyExtParams intriParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(copyNums * sizeof(T)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0));
            AscendC::DataCopyPadExtParams<T> padParams(false, 0, 0, 0);
            AscendC::DataCopyPad(castBuf, inputGm[row * sortDimLength], intriParams, padParams);
            WaitMte2Done();

            // Cast to fp32
            AscendC::Cast(rowBuf, castBuf, AscendC::RoundMode::CAST_NONE, static_cast<uint32_t>(copyNums));
            WaitVDone();

            // Negate for ascending sort
            if (!descending) {
                AscendC::Muls(rowBuf, rowBuf, (float)(-1), copyNums);
                WaitVDone();
            }
        }

        inQueue.EnQue(inBuf);
    }

    __aicore__ inline void Compute(int64_t row) {
        LocalTensor<uint8_t> inBuf = inQueue.DeQue<uint8_t>();
        LocalTensor<float> rowBuf = inBuf.ReinterpretCast<float>();

        // Get sort temp buffer (after rowBuf)
        int64_t sortOffset = sortNum * sizeof(float);
        LocalTensor<float> sortTemp = inBuf[sortOffset].ReinterpretCast<float>();

        // Get sort output buffer (after sortTemp)
        int64_t sortOutOffset = sortOffset + sortNum * sizeof(float) * 2;
        LocalTensor<float> sortOut = inBuf[sortOutOffset].ReinterpretCast<float>();

        // Create indices for sort
        int64_t indexOffset = sortOutOffset + sortNum * sizeof(float) * 2;
        LocalTensor<int32_t> indexBuf = inBuf[indexOffset].ReinterpretCast<int32_t>();
        AscendC::CreateVecIndex(indexBuf, static_cast<int32_t>(0), static_cast<int32_t>(sortNum));
        WaitVDone();

        // Concatenate for sort input format
        LocalTensor<float> concatBuf;
        AscendC::Concat(concatBuf, rowBuf, sortTemp, repeatTimes);

        // Sort (descending float32)
        auto indexBufU32 = indexBuf.ReinterpretCast<uint32_t>();
        AscendC::Sort<float, true>(sortOut, concatBuf, indexBufU32, sortTemp, repeatTimes);
        WaitVDone();

        // Extract sorted values
        LocalTensor<float> outBuf = outQueue.AllocTensor<float>();
        LocalTensor<uint32_t> outIndexU32 = outBuf[sortNum].ReinterpretCast<uint32_t>();
        AscendC::Extract(outBuf, outIndexU32, sortOut, repeatTimes);
        WaitVDone();

        // Negate back if ascending
        if (!descending) {
            AscendC::Muls(outBuf, outBuf, (float)(-1), sortDimLength);
            WaitVDone();
        }

        // Cast back to original dtype if needed
        if constexpr (sizeof(T) != sizeof(float)) {
            AscendC::Cast(outBuf.ReinterpretCast<T>(), outBuf, AscendC::RoundMode::CAST_ROUND, static_cast<uint32_t>(sortDimLength));
            WaitVDone();
        }

        outQueue.EnQue<float>(outBuf);
        inQueue.FreeTensor(inBuf);
    }

    __aicore__ inline void CopyOut(int64_t row) {
        LocalTensor<float> outBuf = outQueue.DeQue<float>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: direct copy
            AscendC::DataCopyPad(outputGm[row * sortDimLength], outBuf,
                AscendC::DataCopyExtParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(sortDimLength * sizeof(float)),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0)));
        } else {
            // FP16/BF16: copy casted data
            AscendC::DataCopyPad(outputGm[row * sortDimLength], outBuf.ReinterpretCast<T>(),
                AscendC::DataCopyExtParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(sortDimLength * sizeof(T)),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0)));
        }
        WaitMte3Done();

        outQueue.FreeTensor(outBuf);
    }

private:
    AscendC::TPipe *pipe;
    AscendC::TQue<AscendC::QuePosition::VECIN, 1> inQueue;
    AscendC::TQue<AscendC::QuePosition::VECOUT, 1> outQueue;

    AscendC::GlobalTensor<T> inputGm;
    AscendC::GlobalTensor<T> outputGm;

    int64_t totalRows;
    int64_t sortDimLength;
    int64_t descending;
    int64_t sortNum;
    int64_t repeatTimes;
};

extern "C" __global__ __aicore__ void sort_kernel(
    GM_ADDR input, GM_ADDR output,
    int64_t totalRows, int64_t sortDimLength, int64_t descending, int64_t dtypeSize) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AscendC::CoreType::AIC) {
        return;
    }

    AscendC::TPipe pipe;

    if (dtypeSize == 4) {
        SortKernel<float> op;
        op.Init(input, output, totalRows, sortDimLength, descending, &pipe);
        op.Process();
    } else if (dtypeSize == 2) {
        // Use half for fp16 and bf16 (both 2 bytes)
        SortKernel<half> op;
        op.Init(input, output, totalRows, sortDimLength, descending, &pipe);
        op.Process();
    }
}
