#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_sort_kernel.h"

#include <torch/extension.h>
#include <algorithm>

namespace ascend_kernel {

at::Tensor sort(const at::Tensor &self, int64_t dim, int64_t descending) {
    TORCH_CHECK(self.is_contiguous(), "sort: input must be contiguous");
    TORCH_CHECK(self.scalar_type() == at::kFloat ||
                self.scalar_type() == at::kHalf ||
                self.scalar_type() == at::kBFloat16,
                "sort: only float32, float16, bfloat16 are supported");

    // Normalize dim
    int64_t ndim = self.dim();
    if (dim < 0) {
        dim = ndim + dim;
    }
    TORCH_CHECK(dim >= 0 && dim < ndim, "sort: dim out of range");

    // Create output tensor
    at::Tensor output = at::empty_like(self);

    // For non-last dimension, we need to transpose to make sort dim the last
    // Then transpose back after sorting
    at::Tensor input_work = self;
    at::Tensor output_work = output;
    bool need_transpose = false;
    std::vector<int64_t> perm;

    if (dim != ndim - 1) {
        need_transpose = true;
        // Build permutation: move dim to the end
        perm.reserve(ndim);
        for (int64_t i = 0; i < ndim; ++i) {
            if (i != dim) {
                perm.push_back(i);
            }
        }
        perm.push_back(dim);

        // Transpose input so sort dim becomes last
        input_work = self.permute(perm);
        output_work = at::empty_like(input_work);
    }

    // Now sort along the last dimension
    int64_t totalRows = 1;
    for (int64_t i = 0; i < input_work.dim() - 1; ++i) {
        totalRows *= input_work.size(i);
    }
    int64_t sortDimLength = input_work.size(input_work.dim() - 1);

    // Get platform info
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());

    // Determine dtype size
    int64_t dtypeSize = 0;
    switch (self.scalar_type()) {
        case at::kFloat: dtypeSize = 4; break;
        case at::kHalf: dtypeSize = 2; break;
        case at::kBFloat16: dtypeSize = 2; break;
        default: dtypeSize = 4; break;
    }

    // Launch kernel
    uint32_t blockDim = static_cast<uint32_t>(std::min(coreNum, totalRows));
    if (blockDim == 0) blockDim = 1;

    EXEC_KERNEL_CMD(sort_kernel, blockDim, input_work, output_work,
                    totalRows, sortDimLength, descending, dtypeSize);

    // Transpose back if needed
    if (need_transpose) {
        // Build inverse permutation
        std::vector<int64_t> inv_perm(ndim);
        for (int64_t i = 0; i < ndim; ++i) {
            inv_perm[perm[i]] = i;
        }
        output = output_work.permute(inv_perm);
    } else {
        output = output_work;
    }

    return output;
}

} // namespace ascend_kernel
