        // outQueue buffer (sortNum * sizeof(float)):
        //   [0:sortNum] - sorted output values in fp32
        //   For fp16: reinterpret as half for output

        int64_t inBufSize = sortNum * 4 * sizeof(float);
        int64_t outBufSize = sortNum * sizeof(float);

        pipe->InitBuffer(inQueue, 1, inBufSize);
        pipe->InitBuffer(outQueue, 1, outBufSize);
    }

    __aicore__ inline void Process() {
        int64_t blockIdx = GetBlockIdx();
        int64_t coreNum = GetBlockNum();
        int64_t rowsPerCore = (totalRows + coreNum - 1) / coreNum;
        int64_t coreStart = blockIdx * rowsPerCore;
        int64_t coreEnd = coreStart + rowsPerCore;
        if (coreEnd > totalRows) coreEnd = totalRows;

