39	
40	private:
41	    __aicore__ inline void MrgSortCompute();
42	    __aicore__ inline void CopyOut();
43	
44	protected:
45	    MrgSortParam* param = nullptr;
46	    GlobalTensor<float> gmInputs[4];
47	    LocalTensor<float> ubInputs[4];
48	
49	    int64_t listNum{0};
50	    int64_t remainListNum{0};
51	    int64_t outOffset{0};
52	    int64_t offsets[4];
53	    int64_t listRemainElements[4];
54	    int64_t lengths[4];
55	    int64_t allRemainElements{0};
56	    int64_t curLoopSortedNum{0};
57	
58	    uint16_t validBitTail{0};
59	    uint16_t elementCountListTail[4];
60	    uint32_t listSortedNums[4];
61	    LocalTensor<float> tmpUbInputs[4];
62	
