68	__aicore__ inline void KvMrgSort::ClearCache()
69	{
70	    this->listNum = 0;
71	    this->allRemainElements = 0;
72	    this->outOffset = 0;
73	}
74	
75	__aicore__ inline void KvMrgSort::SetInput(GlobalTensor<float>& gmInput, LocalTensor<float>& ubInput)
76	{
77	    this->gmInputs[listNum] = gmInput;
78	    this->ubInputs[listNum] = ubInput;
79	    this->listNum += 1;
80	}
