88	__aicore__ inline void KvMrgSort::UpdateMrgParam()
89	{
90	    if (this->remainListNum == MERGE_LIST_TWO) {
91	        elementCountListTail[MERGE_LIST_IDX_TWO] = 0;
92	        elementCountListTail[MERGE_LIST_IDX_THREE] = 0;
93	        validBitTail = 0b0011;
94	    } else if (this->remainListNum == MERGE_LIST_THREE) {
95	        elementCountListTail[MERGE_LIST_IDX_THREE] = 0;
96	        validBitTail = 0b0111;
97	    } else if (this->remainListNum == MERGE_LIST_FOUR) {
98	        validBitTail = 0b1111;
99	    } else {
100	        validBitTail = 0b0001;
101	    }
102	}
103	
104	__aicore__ inline void KvMrgSort::CopyIn()
105	{
106	    this->remainListNum = 0;
107	    event_t eventIdMte3ToMte2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE3_MTE2));
108	    SetFlag<HardEvent::MTE3_MTE2>(eventIdMte3ToMte2);
109	    WaitFlag<HardEvent::MTE3_MTE2>(eventIdMte3ToMte2);
110	    for (int64_t i = 0, j = 0; i < listNum; i++) {
111	        lengths[i] = MinVal(param->oneLoopMaxElements, listRemainElements[i]);
112	        if (lengths[i] > 0) {
113	            DataCopy(this->ubInputs[i], this->gmInputs[i][offsets[i]],
114	                     AlignUp(GetSortLen<float>(lengths[i]), sizeof(float)));
115	            tmpUbInputs[j] = this->ubInputs[i];
116	            elementCountListTail[j] = lengths[i];
117	            this->remainListNum += 1;
118	            j++;
119	        }
120	    }
121	}
122	
123	__aicore__ inline void KvMrgSort::MrgSortCompute()
124	{
125	    event_t eventIdMte2ToV = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_V));
126	    SetFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
127	    WaitFlag<HardEvent::MTE2_V>(eventIdMte2ToV);
128	    if (this->remainListNum == MERGE_LIST_TWO) {
129	        MrgSortSrcList sortList = MrgSortSrcList(tmpUbInputs[0], tmpUbInputs[1], tmpUbInputs[0], tmpUbInputs[0]);
130	        MrgSort<float, true>(this->ubOutput, sortList, elementCountListTail, listSortedNums, validBitTail, 1);
131	    } else if (this->remainListNum == MERGE_LIST_THREE) {
132	        MrgSortSrcList sortList = MrgSortSrcList(tmpUbInputs[0], tmpUbInputs[1], tmpUbInputs[MERGE_LIST_IDX_TWO], tmpUbInputs[0]);
133	        MrgSort<float, true>(this->ubOutput, sortList, elementCountListTail, listSortedNums, validBitTail, 1);
134	    } else if (this->remainListNum == MERGE_LIST_FOUR) {
135	        MrgSortSrcList sortList = MrgSortSrcList(tmpUbInputs[0], tmpUbInputs[1], tmpUbInputs[MERGE_LIST_IDX_TWO], tmpUbInputs[MERGE_LIST_IDX_THREE]);
136	        MrgSort<float, true>(this->ubOutput, sortList, elementCountListTail, listSortedNums, validBitTail, 1);
137	    } else {
138	        DataCopy(this->ubOutput, this->tmpUbInputs[0],
139	                 AlignUp(GetSortLen<float>(elementCountListTail[0]), sizeof(float)));
140	        listSortedNums[0] = elementCountListTail[0];
141	    }
142	}
143	
144	__aicore__ inline void KvMrgSort::UpdateSortInfo()
145	{
146	    curLoopSortedNum = 0;
147	    for (int64_t i = 0, j = 0; i < listNum; i++) {
148	        if (lengths[i] > 0) {
149	            listRemainElements[i] -= listSortedNums[j];
150	            allRemainElements -= listSortedNums[j];
151	            offsets[i] += GetSortOffset<float>(listSortedNums[j]);
152	            curLoopSortedNum += listSortedNums[j];
153	            j += 1;
154	        }
155	    }
156	}
157	
158	__aicore__ inline void KvMrgSort::CopyOut()
159	{
160	    DataCopyParams intriParams;
161	    intriParams.blockCount = 1;
162	    intriParams.blockLen = GetSortLen<float>(curLoopSortedNum) * sizeof(float);
163	    event_t eventIdVToMte3 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::V_MTE3));
164	    SetFlag<HardEvent::V_MTE3>(eventIdVToMte3);
165	    WaitFlag<HardEvent::V_MTE3>(eventIdVToMte3);
166	    DataCopyPad(this->gmOutput[outOffset], this->ubOutput, intriParams);
167	    outOffset += GetSortLen<float>(curLoopSortedNum);
168	}
169	
170	__aicore__ inline void KvMrgSort::Init(MrgSortParam* param)
171	{
172	    this->param = param;
173	    this->remainListNum = listNum;
174	    this->allRemainElements = 0;
175	    for (int64_t i = 0; i < listNum; i++) {
176	        offsets[i] = GetSortOffset<float>(param->perListElements * i);
177	        if (i == listNum - 1) {
178	            listRemainElements[i] = param->lastListElements;
179	        } else {
180	            listRemainElements[i] = param->perListElements;
181	        }
182	        allRemainElements += listRemainElements[i];
183	    }
184	}
185	
186	__aicore__ inline void KvMrgSort::Process()
187	{
188	    for (; allRemainElements > 0;) {
189	        CopyIn();
190	        UpdateMrgParam();
191	        MrgSortCompute();
192	        UpdateSortInfo();
193	        CopyOut();
194	    }
195	    ClearCache();
196	}
