26	    __aicore__ inline void Init(
27	        GM_ADDR keys, GM_ADDR values, GM_ADDR sortedKeys, GM_ADDR sortedValues,
28	        GM_ADDR workspace, const SortKernelTiling* tiling, TPipe* tPipe);
29	    __aicore__ inline void Process();
