32	    __aicore__ inline void VBSProcess();
33	    __aicore__ inline void UBSortProcess(int64_t progress, int64_t size, int64_t sn);
34	    __aicore__ inline void VBSCopyIn(int64_t progress, int64_t size, int64_t sn);
35	    __aicore__ inline void UBSortCompute(int64_t progress, int64_t size, int64_t sn);
36	    __aicore__ inline void VBSCopyOut(int64_t progress, int64_t size, int64_t sn);
37	    __aicore__ inline void OneCoreVMSProcess(int64_t listNum, int64_t perListElem, int64_t lastListElem);
