44	    TPipe* pipe;
45	    TQue<QuePosition::VECIN, 1> copyInQueue;
46	    TQue<QuePosition::VECOUT, 1> copyOutQueue;
47	    TBuf<TPosition::VECCALC> tempBuffer;
48	    TBuf<TPosition::VECCALC> sortedBuf;
49	
50	    GlobalTensor<int32_t> keysGm;
51	    GlobalTensor<int32_t> valuesGm;
52	    GlobalTensor<int32_t> sortedKeysGm;
53	    GlobalTensor<int32_t> sortedValuesGm;
54	    GlobalTensor<float> workspaceGms[2];
55	
56	    KvMrgSort mrgsorter;
57	    MrgSortParam mrgsortParam;
58	
59	    int64_t totalLength;
60	    int64_t blockIdx;
61	    int64_t coreNum;
62	    int64_t needCoreNum;
63	    int64_t srcWsIndex = 0;
64	
65	    int64_t listNum;
66	    int64_t perListElements;
67	    int64_t lastListElements;
68	
69	    int64_t sortTotalLength;
70	    int64_t sortCoreLoops;
71	    int64_t sortCoreLoopElements;
72	    int64_t sortCoreLastLoopElements;
73	
74	    int64_t perCoreElements;
75	    int64_t lastCoreElements;
76	    int64_t oneLoopMaxElements;
77	};
78	
79	__aicore__ inline void SortMultiCore::VBSCopyIn(int64_t progress, int64_t size, int64_t sn)
80	{
81	    LocalTensor<int32_t> inLocal = copyInQueue.AllocTensor<int32_t>();
82	    int64_t inOffset = progress * sortCoreLoopElements;
83	    DataCopyExtParams dataCopyParams{
84	        static_cast<uint16_t>(1), static_cast<uint32_t>(size * sizeof(int32_t)), 0, 0, 0};
85	    DataCopyPadExtParams dataCopyPadParams{false, 0, 0, 0};
86	    DataCopyPad(inLocal[0], keysGm[inOffset], dataCopyParams, dataCopyPadParams);
87	    DataCopyPad(inLocal[sn], valuesGm[inOffset], dataCopyParams, dataCopyPadParams);
88	    copyInQueue.EnQue(inLocal);
89	}
90	
91	__aicore__ inline void SortMultiCore::UBSortCompute(int64_t progress, int64_t size, int64_t sn)
92	{
93	    LocalTensor<int32_t> inLocal = copyInQueue.DeQue<int32_t>();
94	    LocalTensor<int32_t> keysLocal = inLocal[0];
95	    LocalTensor<float> keysFp32 = keysLocal.ReinterpretCast<float>();
96	    Cast(keysFp32, keysLocal, RoundMode::CAST_ROUND, sn);
97	    Muls(keysFp32, keysFp32, (float)-1, sn);
98	
99	    int64_t duplicateNum = size % ONE_REPEAT_SORT_NUM;
100	    if (duplicateNum > 0) {
101	        int duplicateIndex = size - duplicateNum;
102	        uint64_t mask0 = UINT64_MAX;
103	        mask0 = mask0 << duplicateNum;
104	        mask0 = mask0 & (UINT64_MAX >> ONE_REPEAT_SORT_NUM);
105	        uint64_t mask[2] = {mask0, 0};
106	        Duplicate(keysFp32[duplicateIndex], MIN_FP32, mask, 1, DST_BLK_STRIDE, DST_REP_STRIDE);
107	    }
108	
109	    LocalTensor<float> concatLocal;
110	    LocalTensor<float> tempTensor = tempBuffer.Get<float>(GetSortLen<float>(sn));
111	    Concat(concatLocal, keysFp32, tempTensor, sn / ONE_REPEAT_SORT_NUM);
112	
113	    LocalTensor<float> sortedLocal = sortedBuf.Get<float>(GetSortLen<float>(sn));
114	    LocalTensor<float> outLocal = copyOutQueue.AllocTensor<float>();
115	    LocalTensor<uint32_t> valuesLocal = inLocal[sn].ReinterpretCast<uint32_t>();
116	    Sort<float, true>(outLocal, concatLocal, valuesLocal, sortedLocal, sn / ONE_REPEAT_SORT_NUM);
117	
118	    copyOutQueue.EnQue<float>(outLocal);
119	    copyInQueue.FreeTensor(inLocal);
120	}
121	
122	__aicore__ inline void SortMultiCore::VBSCopyOut(int64_t progress, int64_t size, int64_t sn)
123	{
124	    LocalTensor<float> outLocal = copyOutQueue.DeQue<float>();
125	    DataCopy(
126	        workspaceGms[0][this->blockIdx * GetSortLen<float>(this->perCoreElements) +
127	                        GetSortLen<float>(progress * sortCoreLoopElements)],
128	        outLocal, AlignUp(GetSortLen<float>(size), sizeof(float)));
129	    copyOutQueue.FreeTensor(outLocal);
130	}
131	
132	__aicore__ inline void SortMultiCore::UBSortProcess(int64_t progress, int64_t size, int64_t sn)
133	{
134	    VBSCopyIn(progress, size, sn);
135	    UBSortCompute(progress, size, sn);
136	    VBSCopyOut(progress, size, sn);
137	}
138	
139	__aicore__ inline void SortMultiCore::InitMrgSort(
140	    KvMrgSort* sorter, int64_t ln, int64_t coreOff, int64_t loopOff)
141	{
142	    GlobalTensor<float> srcWsGm = workspaceGms[srcWsIndex][blockIdx * coreOff + loopOff];
143	    LocalTensor<float> inLocal = copyInQueue.AllocTensor<float>();
144	    LocalTensor<float> outLocal = copyOutQueue.AllocTensor<float>();
145	    for (int64_t i = 0; i < ln; i++) {
146	        LocalTensor<float> inLocalT = inLocal[GetSortLen<float>(this->oneLoopMaxElements) * i];
147	        sorter->SetInput(srcWsGm, inLocalT);
148	    }
149	    GlobalTensor<float> dstWsGm = workspaceGms[1 - srcWsIndex][blockIdx * coreOff + loopOff];
150	    sorter->SetOutput(dstWsGm, outLocal);
151	    copyInQueue.FreeTensor(inLocal);
152	    copyOutQueue.FreeTensor(outLocal);
153	}
154	
155	__aicore__ inline void SortMultiCore::InitMrgSortOut(
156	    KvMrgSortOut* sorter, int64_t ln, int64_t coreOff)
157	{
158	    GlobalTensor<float> srcWsGm = workspaceGms[srcWsIndex];
159	    LocalTensor<float> inLocal = copyInQueue.AllocTensor<float>();
160	    LocalTensor<float> outLocal = copyOutQueue.AllocTensor<float>();
161	
162	    for (int64_t i = 0; i < ln; i++) {
163	        LocalTensor<float> inLocalT = inLocal[GetSortLen<float>(this->oneLoopMaxElements) * i];
164	        sorter->SetInput(srcWsGm, inLocalT);
165	    }
166	
167	    LocalTensor<float> outLocalV = outLocal[this->oneLoopMaxElements * MAX_MRGSORT_LIST];
168	    sorter->SetOutput(this->sortedKeysGm, this->sortedValuesGm, outLocal, outLocalV);
169	
170	    LocalTensor<float> tb = sortedBuf.Get<float>(
171	        GetSortLen<float>(this->oneLoopMaxElements) * MAX_MRGSORT_LIST);
172	    sorter->SetBuffer(tb);
173	    copyInQueue.FreeTensor(inLocal);
174	    copyOutQueue.FreeTensor(outLocal);
175	}
176	
177	__aicore__ inline void SortMultiCore::OneCoreVMSProcess(
178	    int64_t ln, int64_t perListElem, int64_t lastListElem)
179	{
180	    int64_t coreOffset = GetSortLen<float>(this->perCoreElements);
181	    mrgsortParam.oneLoopMaxElements = this->oneLoopMaxElements;
182	
183	    for (int64_t i = 0; ln >= 1; i++) {
184	        int64_t loops = (ln + MAX_MRGSORT_LIST - 1) / MAX_MRGSORT_LIST;
185	        int64_t remainLn = ln - (loops - 1) * MAX_MRGSORT_LIST;
186	
187	        mrgsortParam.perListElements = perListElem;
188	        mrgsortParam.lastListElements = perListElem;
189	
190	        int64_t loopOffset = GetSortLen<float>(mrgsortParam.perListElements * MAX_MRGSORT_LIST);
191	        for (int64_t loop = 0; loop < loops - 1; loop++) {
192	            InitMrgSort(&mrgsorter, MAX_MRGSORT_LIST, coreOffset, loop * loopOffset);
193	            mrgsorter.Init(&mrgsortParam);
194	            mrgsorter.Process();
195	        }
196	
197	        mrgsortParam.perListElements = perListElem;
198	        mrgsortParam.lastListElements = lastListElem;
199	        InitMrgSort(&mrgsorter, remainLn, coreOffset, (loops - 1) * loopOffset);
200	        mrgsorter.Init(&mrgsortParam);
201	        mrgsorter.Process();
202	
203	        ln = loops;
204	        lastListElem = perListElem * (remainLn - 1) + lastListElem;
205	        perListElem = perListElem * MAX_MRGSORT_LIST;
206	        srcWsIndex = (srcWsIndex + 1) % WORK_GM_NUM;
207	
208	        if (loops == 1) break;
209	    }
210	}
211	
212	__aicore__ inline void SortMultiCore::VBSProcess()
213	{
214	    if (this->blockIdx < this->needCoreNum) {
215	        int64_t sn = CeilDiv(sortCoreLoopElements, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
216	        for (int64_t loop = 0; loop < sortCoreLoops - 1; loop++) {
217	            UBSortProcess(loop, sortCoreLoopElements, sn);
218	        }
219	        sn = CeilDiv(sortCoreLastLoopElements, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
220	        UBSortProcess(sortCoreLoops - 1, sortCoreLastLoopElements, sn);
221	
222	        OneCoreVMSProcess(sortCoreLoops, sortCoreLoopElements, sortCoreLastLoopElements);
223	    }
224	
225	    // After OneCoreVMSProcess, if the last core had a different number of loops
226	    // it may have ended with srcWsIndex pointing to a different buffer.
227	    // Fix: compute the expected srcWsIndex from core 0's perspective,
228	    // and if mismatched, copy the data to the correct buffer.
229	    int64_t perCoreLoopsCalc = CeilDiv(this->perCoreElements, sortCoreLoopElements);
230	    int64_t mainMergeRounds = 0;
231	    {
232	        int64_t ln = perCoreLoopsCalc;
233	        while (ln > 1) {
234	            ln = CeilDiv(ln, MAX_MRGSORT_LIST);
235	            mainMergeRounds++;
236	        }
237	    }
238	    int64_t expectedWsIndex = mainMergeRounds % WORK_GM_NUM;
239	
240	    if (this->blockIdx < this->needCoreNum && srcWsIndex != expectedWsIndex) {
241	        int64_t coreOff = this->blockIdx * GetSortLen<float>(this->perCoreElements);
242	        int64_t dataLen = AlignUp(GetSortLen<float>(this->sortTotalLength), sizeof(float));
243	
244	        LocalTensor<float> tmpBuf = copyInQueue.AllocTensor<float>();
245	        int64_t bufFloats = CeilDiv(
246	            MaxVal(this->oneLoopMaxElements * MAX_MRGSORT_LIST, sortCoreLoopElements),
247	            ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM * 2;
248	
249	        for (int64_t off = 0; off < dataLen; off += bufFloats) {
250	            int64_t chunk = MinVal(bufFloats, dataLen - off);
251	            int64_t alignChunk = AlignUp(chunk, sizeof(float));
252	
253	            event_t e1 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE3_MTE2));
254	            SetFlag<HardEvent::MTE3_MTE2>(e1);
255	            WaitFlag<HardEvent::MTE3_MTE2>(e1);
256	            DataCopy(tmpBuf, workspaceGms[srcWsIndex][coreOff + off], alignChunk);
257	
258	            event_t e2 = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_MTE3));
259	            SetFlag<HardEvent::MTE2_MTE3>(e2);
260	            WaitFlag<HardEvent::MTE2_MTE3>(e2);
261	            DataCopy(workspaceGms[expectedWsIndex][coreOff + off], tmpBuf, alignChunk);
262	        }
263	        copyInQueue.FreeTensor(tmpBuf);
264	    }
265	    srcWsIndex = expectedWsIndex;
266	
267	    AscendC::SyncAll();
268	}
