270	__aicore__ inline void SortMultiCore::VMSProcess()
271	{
272	    int64_t currentStageNeedCoreNum = this->needCoreNum;
273	    perListElements = this->perCoreElements;
274	    lastListElements = this->lastCoreElements;
275	    listNum = this->needCoreNum;
276	
277	    for (; listNum > MAX_MRGSORT_LIST;) {
278	        currentStageNeedCoreNum = CeilDiv(listNum, MAX_MRGSORT_LIST);
279	        int64_t coreOffset = GetSortLen<float>(perListElements * MAX_MRGSORT_LIST);
280	        int64_t remainLn = listNum - (currentStageNeedCoreNum - 1) * MAX_MRGSORT_LIST;
281	
282	        if (this->blockIdx < currentStageNeedCoreNum - 1) {
283	            mrgsortParam.perListElements = perListElements;
284	            mrgsortParam.lastListElements = perListElements;
285	            mrgsortParam.oneLoopMaxElements = this->oneLoopMaxElements;
286	            InitMrgSort(&mrgsorter, MAX_MRGSORT_LIST, coreOffset, 0);
287	            mrgsorter.Init(&mrgsortParam);
288	            mrgsorter.Process();
289	        } else if (this->blockIdx == currentStageNeedCoreNum - 1) {
290	            mrgsortParam.perListElements = perListElements;
291	            mrgsortParam.lastListElements = lastListElements;
292	            mrgsortParam.oneLoopMaxElements = this->oneLoopMaxElements;
293	            InitMrgSort(&mrgsorter, remainLn, coreOffset, 0);
294	            mrgsorter.Init(&mrgsortParam);
295	            mrgsorter.Process();
296	        }
297	        listNum = currentStageNeedCoreNum;
298	        srcWsIndex = (srcWsIndex + 1) % WORK_GM_NUM;
299	        lastListElements = perListElements * (remainLn - 1) + lastListElements;
300	        perListElements = perListElements * MAX_MRGSORT_LIST;
301	        AscendC::SyncAll();
302	    }
303	}
