305	__aicore__ inline void SortMultiCore::SortOutProcess()
306	{
307	    if (this->blockIdx < 1) {
308	        mrgsortParam.perListElements = perListElements;
309	        mrgsortParam.lastListElements = lastListElements;
310	        mrgsortParam.oneLoopMaxElements = this->oneLoopMaxElements;
311	
312	        KvMrgSortOut sorter;
313	        InitMrgSortOut(&sorter, listNum, GetSortLen<float>(perListElements));
314	        sorter.Init(&mrgsortParam, pipe);
315	        sorter.Process();
316	    }
317	    AscendC::SyncAll();
318	}
