320	__aicore__ inline void SortMultiCore::Init(
321	    GM_ADDR keys, GM_ADDR values, GM_ADDR sortedKeys, GM_ADDR sortedValues,
322	    GM_ADDR workspace, const SortKernelTiling* tiling, TPipe* tPipe)
323	{
324	    this->pipe = tPipe;
325	    this->totalLength = tiling->totalLength;
326	    this->coreNum = tiling->coreNum;
327	    this->needCoreNum = tiling->needCoreNum;
328	    this->blockIdx = GetBlockIdx();
329	
330	    this->perCoreElements = tiling->perCoreElements;
331	    this->lastCoreElements = tiling->lastCoreElements;
332	    this->oneLoopMaxElements = tiling->oneLoopMaxElements;
333	
334	    int64_t perCorePerLoopElem = tiling->perCorePerLoopElements;
335	    int64_t lastCorePerLoopElem = tiling->lastCorePerLoopElements;
336	
337	    this->sortTotalLength = this->perCoreElements;
338	    if (this->blockIdx == this->needCoreNum - 1) {
339	        this->sortTotalLength = this->lastCoreElements;
340	        sortCoreLoops = tiling->lastCoreLoops;
341	        sortCoreLoopElements = tiling->lastCorePerLoopElements;
342	        sortCoreLastLoopElements = tiling->lastCoreLastLoopElements;
343	    } else {
344	        sortCoreLoops = tiling->perCoreLoops;
345	        sortCoreLoopElements = tiling->perCorePerLoopElements;
346	        sortCoreLastLoopElements = tiling->perCoreLastLoopElements;
347	    }
348	
349	    keysGm.SetGlobalBuffer(
350	        (__gm__ int32_t*)keys + this->blockIdx * this->perCoreElements,
351	        this->sortTotalLength);
352	    valuesGm.SetGlobalBuffer(
353	        (__gm__ int32_t*)values + this->blockIdx * this->perCoreElements,
354	        this->sortTotalLength);
355	    sortedKeysGm.SetGlobalBuffer((__gm__ int32_t*)sortedKeys, this->totalLength);
356	    sortedValuesGm.SetGlobalBuffer((__gm__ int32_t*)sortedValues, AlignUp(this->totalLength, sizeof(int32_t)));
357	
358	    int64_t kvFactor = 2;
359	    int64_t perCoreSortLen = GetSortLen<float>(this->perCoreElements);
360	    int64_t oneBufSize = this->needCoreNum * perCoreSortLen;
361	    workspaceGms[0].SetGlobalBuffer(
362	        (__gm__ float*)workspace,
363	        oneBufSize);
364	    workspaceGms[1].SetGlobalBuffer(
365	        (__gm__ float*)workspace + oneBufSize,
366	        oneBufSize);
367	
368	    int64_t bufferSize = CeilDiv(
369	        MaxVal(this->oneLoopMaxElements * MAX_MRGSORT_LIST, sortCoreLoopElements),
370	        ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM * sizeof(int32_t) * kvFactor;
371	    pipe->InitBuffer(copyInQueue, 1, bufferSize);
372	    pipe->InitBuffer(copyOutQueue, 1, bufferSize);
373	    pipe->InitBuffer(tempBuffer, bufferSize);
374	    pipe->InitBuffer(sortedBuf, bufferSize);
375	}
