#include "kernel_operator.h"

using namespace AscendC;

constexpr int64_t ONE_REPEAT_SORT_NUM = 32;
constexpr int64_t BLOCK_BYTES = 32;
constexpr float MIN_FP32 = -3.402823466e38f;
constexpr int64_t DST_BLK_STRIDE = 1;
constexpr int64_t DST_REP_STRIDE = 8;

__aicore__ inline int64_t CeilDiv(int64_t a, int64_t b) {
    if (b == 0) return 0;
    return (a + b - 1) / b;
}

__aicore__ inline int64_t AlignUp(int64_t elementNum, int64_t bytesPerElement) {
    if (bytesPerElement == 0) return 0;
    return (elementNum * bytesPerElement + BLOCK_BYTES - 1) / BLOCK_BYTES * BLOCK_BYTES / bytesPerElement;
}

// Sort format: each 32-element group needs 32 keys + 32 indices = 64 floats
__aicore__ inline int64_t GetSortLen(int64_t elementNum) {
    return CeilDiv(elementNum, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM * 2;
}

// Wait functions for pipeline synchronization
__aicore__ inline void WaitMte2Done() {
    event_t evt = static_cast<event_t>(GetTPipePtr()->FetchEventID(HardEvent::MTE2_S));
    SetFlag<HardEvent::MTE2_S>(evt);
    WaitFlag<HardEvent::MTE2_S>(evt);
}

