template <typename T>
class SortKernel {
public:
    __aicore__ inline SortKernel() {}

    __aicore__ inline void Init(
        GM_ADDR input, GM_ADDR output,
        int64_t totalRows, int64_t sortDimLength, int64_t descending,
        TPipe *pipe) {
        this->pipe = pipe;
        this->totalRows = totalRows;
        this->sortDimLength = sortDimLength;
        this->descending = descending;
        // Align to 32 elements for Sort
        this->sortNum = CeilDiv(sortDimLength, ONE_REPEAT_SORT_NUM) * ONE_REPEAT_SORT_NUM;
        this->repeatTimes = sortNum / ONE_REPEAT_SORT_NUM;

        inputGm.SetGlobalBuffer((__gm__ T *)input, totalRows * sortDimLength);
        outputGm.SetGlobalBuffer((__gm__ T *)output, totalRows * sortDimLength);

        // Buffer sizes for sort computation:
        // inQueue (copy in): holds input data
        //   For fp32: sortNum floats
        //   For fp16: sortNum halfs + sortNum floats (cast buffer)
        // outQueue (copy out): holds sorted output
        //   For fp32: sortNum floats
        //   For fp16: sortNum floats (cast back to half)
        // tempBuf (TBuf): holds sort temp + sort output (sortNum * 2 floats each)
        //   Size = sortNum * 2 * sizeof(float) * 2 = sortNum * 4 * sizeof(float)
        //   (sort format is 2x elements: keys + indices)

        int64_t inQueueSize = sortNum * sizeof(float) * 2;  // keys + indices space
        int64_t outQueueSize = sortNum * sizeof(float) * 2;  // sorted keys + indices
        int64_t tempBufSize = GetSortLen(sortNum) * sizeof(float);  // sort temp/work buffer

        pipe->InitBuffer(inQueue, 1, inQueueSize);
        pipe->InitBuffer(outQueue, 1, outQueueSize);
        pipe->InitBuffer(tempBuf, tempBufSize);
    }

    __aicore__ inline void Process() {
        int64_t blockIdx = GetBlockIdx();
        int64_t coreNum = GetBlockNum();
        int64_t rowsPerCore = (totalRows + coreNum - 1) / coreNum;
        int64_t coreStart = blockIdx * rowsPerCore;
        int64_t coreEnd = coreStart + rowsPerCore;
        if (coreEnd > totalRows) coreEnd = totalRows;

        for (int64_t row = coreStart; row < coreEnd; ++row) {
            CopyIn(row);
            Compute(row);
            CopyOut(row);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t row) {
        LocalTensor<float> inLocal = inQueue.AllocTensor<float>();
        uint64_t copyNums = sortDimLength;

        // Fill with -inf for padding
        Duplicate(inLocal, static_cast<float>(-__builtin_inff()), sortNum);
        WaitVDone();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: copy directly to inLocal
            bool needPad = (copyNums % 8 != 0);
            uint8_t rightPad = needPad ? static_cast<uint8_t>(8 - (copyNums % 8)) : 0;
            DataCopyExtParams intriParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(copyNums * sizeof(float)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0));
            DataCopyPadExtParams<float> padParams(
                needPad, 0, rightPad, static_cast<float>(-__builtin_inff()));
            DataCopyPad(inLocal, inputGm[row * sortDimLength], intriParams, padParams);
            WaitMte2Done();
        } else {
            // FP16/BF16: copy to cast buffer then cast to fp32
            // Use second half of inLocal as cast buffer
            LocalTensor<T> castBuf = inLocal[sortNum].ReinterpretCast<T>();
            DataCopyExtParams intriParams(
                static_cast<uint16_t>(1),
                static_cast<uint32_t>(copyNums * sizeof(T)),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0),
                static_cast<uint32_t>(0));
            DataCopyPadExtParams<T> padParams(false, 0, 0, 0);
            DataCopyPad(castBuf, inputGm[row * sortDimLength], intriParams, padParams);
            WaitMte2Done();

            // Cast to fp32 into first half of inLocal
            Cast(inLocal, castBuf, RoundMode::CAST_NONE, static_cast<uint32_t>(copyNums));
            WaitVDone();
        }

        // Negate for ascending sort (descending=false)
        if (!descending) {
            Muls(inLocal, inLocal, (float)(-1), copyNums);
            WaitVDone();
        }

        inQueue.EnQue(inLocal);
    }

    __aicore__ inline void Compute(int64_t row) {
        LocalTensor<float> inLocal = inQueue.DeQue<float>();

        // Create indices at offset sortNum in inLocal
        LocalTensor<int32_t> indexBuf = inLocal[sortNum].ReinterpretCast<int32_t>();
        CreateVecIndex(indexBuf, static_cast<int32_t>(0), static_cast<int32_t>(sortNum));
        WaitVDone();

        // Get temp buffer for Concat/Sort from TBuf
        LocalTensor<float> tempTensor = tempBuf.Get<float>(GetSortLen(sortNum));

        // Concatenate keys and indices into sort format
        LocalTensor<float> concatBuf;
        Concat(concatBuf, inLocal, tempTensor, repeatTimes);

        // Sort output buffer (from TBuf)
        LocalTensor<float> sortedLocal = tempBuf.Get<float>(GetSortLen(sortNum));

        // Sort (descending float32)
        auto indexBufU32 = indexBuf.ReinterpretCast<uint32_t>();
        Sort<float, true>(sortedLocal, concatBuf, indexBufU32, tempTensor, repeatTimes);
        WaitVDone();

        // Extract sorted values to outQueue
        LocalTensor<float> outLocal = outQueue.AllocTensor<float>();
        LocalTensor<uint32_t> outIndexU32 = outLocal[sortNum].ReinterpretCast<uint32_t>();
        Extract(outLocal, outIndexU32, sortedLocal, repeatTimes);
        WaitVDone();

        // Negate back if ascending
        if (!descending) {
            Muls(outLocal, outLocal, (float)(-1), sortDimLength);
            WaitVDone();
        }

        // Cast back to original dtype if needed
        if constexpr (sizeof(T) != sizeof(float)) {
            Cast(outLocal.ReinterpretCast<T>(), outLocal, RoundMode::CAST_ROUND, static_cast<uint32_t>(sortDimLength));
            WaitVDone();
        }

        outQueue.EnQue<float>(outLocal);
        inQueue.FreeTensor(inLocal);
    }

    __aicore__ inline void CopyOut(int64_t row) {
        LocalTensor<float> outLocal = outQueue.DeQue<float>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // FP32: direct copy
            DataCopyPad(outputGm[row * sortDimLength], outLocal,
                DataCopyExtParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(sortDimLength * sizeof(float)),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0)));
        } else {
            // FP16/BF16: copy casted data
            DataCopyPad(outputGm[row * sortDimLength], outLocal.ReinterpretCast<T>(),
                DataCopyExtParams(
                    static_cast<uint16_t>(1),
                    static_cast<uint32_t>(sortDimLength * sizeof(T)),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0),
                    static_cast<uint32_t>(0)));
        }
        WaitMte3Done();

        outQueue.FreeTensor(outLocal);
    }

private:
    TPipe *pipe;
    TQue<QuePosition::VECIN, 1> inQueue;
    TQue<QuePosition::VECOUT, 1> outQueue;
    TBuf<TPosition::VECCALC> tempBuf;

    GlobalTensor<T> inputGm;
    GlobalTensor<T> outputGm;

    int64_t totalRows;
    int64_t sortDimLength;
    int64_t descending;
    int64_t sortNum;
    int64_t repeatTimes;
};

extern "C" __global__ __aicore__ void sort_kernel(
    GM_ADDR input, GM_ADDR output,
    int64_t totalRows, int64_t sortDimLength, int64_t descending, int64_t dtypeSize) {
    KERNEL_TASK_TYPE_DEFAULT(KERNEL_TYPE_MIX_AIV_1_0);
    if (g_coreType == AIC) {
        return;
    }

    TPipe pipe;

    if (dtypeSize == 4) {
        SortKernel<float> op;
        op.Init(input, output, totalRows, sortDimLength, descending, &pipe);
        op.Process();
    } else if (dtypeSize == 2) {
        SortKernel<half> op;
        op.Init(input, output, totalRows, sortDimLength, descending, &pipe);
        op.Process();
    }
}
