20	at::Tensor sort(const at::Tensor &self, int64_t dim, int64_t descending) {
21	    TORCH_CHECK(self.is_contiguous(), "sort: input must be contiguous");
22	    TORCH_CHECK(self.scalar_type() == at::kFloat ||
23	                self.scalar_type() == at::kHalf ||
24	                self.scalar_type() == at::kBFloat16,
25	                "sort: only float32, float16, bfloat16 are supported");
26	
27	    // Normalize dim
28	    int64_t ndim = self.dim();
29	    if (dim < 0) {
30	        dim = ndim + dim;
31	    }
32	    TORCH_CHECK(dim >= 0 && dim < ndim, "sort: dim out of range");
33	
34	    // Create output tensor
35	    at::Tensor output = at::empty_like(self);
36	
37	    // For non-last dimension, we need to transpose to make sort dim the last
38	    // Then transpose back after sorting
39	    at::Tensor input_work = self;
40	    at::Tensor output_work = output;
41	    bool need_transpose = false;
42	    std::vector<int64_t> perm;
43	
44	    if (dim != ndim - 1) {
45	        need_transpose = true;
46	        // Build permutation: move dim to the end
47	        perm.reserve(ndim);
48	        for (int64_t i = 0; i < ndim; ++i) {
49	            if (i != dim) {
50	                perm.push_back(i);
51	            }
52	        }
